static const int kMaxBins = 32;
T costBest = std::numeric_limits<T>::max();
*minCostAxis = 0;
bool found = false;

for (int axis = 0; axis < 3; axis++) {
    T extent = bmax[axis] - bmin[axis];
    if (extent <= 0) continue;

    T scale = static_cast<T>(kMaxBins) / extent;
    T inv_scale = extent / static_cast<T>(kMaxBins);

    int left_count = 0;
    int right_count = bins->GetNumBins(axis);
    if (right_count <= 1) continue;

    T min_cost = std::numeric_limits<T>::max();
    T best_cut_pos = bmin[axis];
    int best_bin_id = -1;

    for (int i = 0; i < bins->GetNumBins(axis) - 1; i++) {
        left_count += bins->GetBinSize(axis, i);
        right_count -= bins->GetBinSize(axis, i);

        if (left_count == 0 || right_count == 0) {
            continue;
        }

        T left_edge = bmin[axis] + static_cast<T>(i) * inv_scale;
        T right_edge = bmin[axis] + static0<T>(i + 1) * inv_scale;
        T cut_pos_bin = (left_edge + right_edge) * static_cast<T>(0.5);

        T left_area = 0, right_area = 0;
        for (int a = 0; a < 3; a++) {
            if (a == axis) continue;
            left_area += (cut_pos_bin - bmin[a]) * (bmax[a] - bmin[a]);
            right_area += (bmax[a] - bmin[a]) * (bmax[a] - cut_pos_bin);
        }

        T cost = left_area * static_cast<T>(left_count) + right_area * static_cast<T>(right_count);
        if (cost < min_cost) {
            min_cost = cost;
            best_cut_pos = cut_pos_bin;
            best_bin_id = i;
        }
    }

    if (best_bin_id != -1 && min_cost < costBest) {
        costBest = min_cost;
        cut_pos[axis] = best_cut_pos;
        *minCostAxis = axis;
        found = true;
    } else {
        cut_pos[axis] = best_cut_pos;
    }
}

return found;
// END_CODE

